private static Map<TypeVariable<?>, Type> buildTypeVariableMap(Class<?> clazz) {
    Map<TypeVariable<?>, Type> map = new java.util.HashMap<>();
    for (TypeVariable<?> tv : clazz.getTypeParameters()) {
        map.put(tv, tv);
    }
    // Process interfaces and superclass
    resolveInheritTypes(clazz, map);
    return map;
}

private static void resolveInheritTypes(Class<?> clazz, Map<TypeVariable<?>, Type> map) {
    Type genericSuper = clazz.getGenericSuperclass();
    if (genericSuper != null) {
        resolveTypeRecursively(genericSuper, map);
    }
    for (Type iface : clazz.getGenericInterfaces()) {
        resolveTypeRecursively(iface, map);
    }
}

private static void resolveTypeRecursively(Type type, Map<TypeVariable<?>, Type> map) {
    if (type instanceof ParameterizedType) {
        ParameterizedType p = (ParameterizedType) type;
        Type raw = p.getRawType();
        if (raw instanceof Class<?>) {
            Class<?> rawClass = (Class<?>) raw;
            TypeVariable<?>[] typeParams = rawClass.getTypeParameters();
            Type[] actualArgs = p.getActualTypeArguments();
            for (int i = 0; i < typeParams.length; i++) {
                map.put(typeParams[i], actualArgs[i]);
            }
            resolveTypeRecursively(rawClass, map);
            for (Type arg : actualArgs) {
                resolveTypeRecursively(arg, map);
            }
        } else {
            resolveTypeRecursively(raw, map);
            for (Type arg : p.getActualTypeArguments()) {
                resolveTypeRecursively(arg, map);
            }
        }
    } else if (type instanceof Class<?>) {
        Class<?> c = (Class<?>) type;
        resolveInheritTypes(c, map);
    }
    // Wildcard and other types ignored
}

private static Class<?> resolveTypeArgument(Type type, Map<TypeVariable<?>, Type> map) {
    if (type instanceof Class<?>) {
        return (Class<?>) type;
    }
    if (type instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) type).getRawType();
    }
    if (type instanceof TypeVariable<?>) {
        Type mapped = map.get(type);
        if (mapped == null) {
            return null;
        }
        return resolveTypeArgument(mapped, map);
    }
    return null; // Wildcard, etc., not resolvable
}

