private static java.util.Map<java.lang.reflect.TypeVariable<?>, java.lang.reflect.Type> buildTypeVariableMap(Class<?> clazz) {
    java.util.Map<java.lang.reflect.TypeVariable<?>, java.lang.reflect.Type> map = new java.util.HashMap<>();
    // map own
    for (java.lang.reflect.TypeVariable<?> tv : clazz.getTypeParameters()) {
        map.put(tv, tv);
    }
    // add super and interfaces
    java.util.Deque<java.lang.reflect.Type> stack = new java.util.ArrayDeque<>();
    java.lang.reflect.Type superType = clazz.getGenericSuperclass();
    if (superType != null) stack.push(superType);
    for (java.lang.reflect.Type itf : clazz.getGenericInterfaces()) {
        stack.push(itf);
    }
    while (!stack.isEmpty()) {
        java.lang.reflect.Type t = stack.pop();
        resolveTypeVariablesRecursive(t, map);
    }
    return map;
}

