    // Build base list
    String[] pathParts = path.split("/", -1);
    List<String> base = new ArrayList<>();
    for (String p: pathParts) {
        base.add(p);
    }
    boolean pathEndsWithSlash = path.endsWith("/");
    if (!base.isEmpty()) {
        int lastIdx = base.size() - 1;
        String last = base.get(lastIdx);
        if (pathEndsWithSlash) {
            if (last.isEmpty()) {
                base.remove(lastIdx);
            }
        } else {
            if (!last.isEmpty()) {
                base.remove(lastIdx);
            }
        }
    }

    // Process relative parts
    String[] relParts = relativePath.split("/", -1);
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!base.isEmpty()) {
                // If we are at root and base contains only empty string, we should not remove it to keep root slash
                if (base.size() == 1 && base.get(0).isEmpty()) {
                    // root, cannot go higher
                    continue;
                }
                base.remove(base.size() - 1);
