        } else {
            base.add(part);
        }
    }

    // Join
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < base.size(); i++) {
        String part = base.get(i);
        if (i == 0 && part.isEmpty()) {
            sb.append("/");
            continue;
        }
        if (i > 0 && !sb.toString().endsWith("/")) {
            sb.append("/");
        }
        sb.append(part);
    }
    return sb.toString();
}

